// Common landing point for both entry paths (the real "When Executed by
// Parent" caller, and "Test manually" for standalone testing), so the
// normalizer downstream can reliably reference ONE upstream node by name
// for account_id/channel, regardless of which trigger actually ran.
return $input.all();

// Maps clockworks/tiktok-scraper's (Apify) dataset output into the standard
// row schema the main report expects. Each dataset item IS one video --
// no joining two arrays needed, unlike the old ScrapegraphAI shape.
//
// This actor only scrapes video posts (profileScrapeSections: ['videos']),
// so every row here is classified 'Video' -- TikTok photo-carousel posts
// aren't returned by this actor and are out of scope for now.
//
// account_id/channel come from 'Prepare request' (the shared node both
// entry paths route through), matched via pairedItem rather than raw
// forEach index -- one account can expand into many video items here,
// so index alignment (which worked for the old 1-item-per-account
// ScrapegraphAI shape) would silently misattribute rows past the first.

function srcIndex(item, fallback) {
  const pi = item.pairedItem;
  if (typeof pi === 'number') return pi;
  if (Array.isArray(pi) && pi.length) return pi[0].item;
  if (pi && typeof pi === 'object' && pi.item !== undefined) return pi.item;
  return fallback;
}

const items = $input.all();

if (!items.length) {
  const ctx = $('Prepare request').first().json;
  return [{
    json: {
      platform: 'TikTok',
      channel: ctx.channel,
      skipped: true,
      reason: 'No posts found on the profile (blocked, empty, or private).',
    },
    pairedItem: 0,
  }];
}

return items.map((item, index) => {
  const ctx = $('Prepare request').itemMatching(srcIndex(item, index)).json;
  const v = item.json;

  return {
    json: {
      platform: 'TikTok',
      channel: ctx.channel,
      account_id: ctx.account_id,
      likes_label: 'Likes',
      id: String(v.id),
      title: String(v.text || '').slice(0, 100),
      type: 'Video',
      views: v.playCount ?? null,
      likes: v.diggCount ?? null,
      comments: v.commentCount ?? null,
      shares: v.shareCount ?? null,
      permalink: v.webVideoUrl || `https://www.tiktok.com/@${ctx.account_id}/video/${v.id}`,
      created_at: v.createTimeISO || null,
      insights_ok: true,
    },
    pairedItem: 0,
  };
});

// Test data for standalone runs -- the real caller is the main workflow's
// Accounts config, which passes one item like this per enabled TikTok account.
// account_id must be the bare handle (tiktok.com/@<handle>), not a numeric ID.
return [
  { json: { platform: 'TikTok', channel: 'Brand B', account_id: 'brand_b' } },
  { json: { platform: 'TikTok', channel: 'Brand A', account_id: 'brand_a' } },
];
